"""Rebuild the reviewed Delhi police slice; no automatic inference of misconduct."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / 'delhi-security.json'
TODAY = '2026-10-07'
S = {'sources': [], 'entities': [], 'relationships': [], 'records': [], 'localities': [{'id': 'delhi', 'name': 'Delhi', 'stateCode': 'DL', 'kind': 'city', 'aliases': ['New Delhi', 'NCT of Delhi']}]}
DOM = ['security', 'public-funds', 'justice']

def source(id, title, url, publisher, date, locator, summary, limitations=None, tier='documented'):
    S['sources'].append(dict(id=id, title=title, url=url, publisher=publisher, publishedAt=date, retrievedAt=TODAY, locator=locator, summary=summary, tier=tier, limitations=limitations or []))

def geo(ids, national=False):
    return [dict(scope='national' if national else 'city', stateCodes=[] if national else ['DL'], localityIds=[] if national else ['delhi'], basis='national-context' if national else 'programme-coverage', note='National institution or funding framework; no national expenditure is allocated to Delhi merely because the institution has a Delhi office.' if national else 'Delhi Police programme or public procurement in the NCT; city association, not a building, person, operational site or exact asset coordinate.', sourceIds=ids)]

def dims(ids, layers=None, national=False, limitations=None):
    return dict(domains=DOM.copy(), layers=layers or ['procurement', 'funding', 'review'], geography=geo(ids, national), route='/allegations', sourceIds=ids, limitations=limitations or [])

def entity(id, label, typ, summary, ids, national=False, resolved=True, identity=None):
    S['entities'].append(dict(id=id, label=label, type=typ, resolved=resolved, identityBasis=identity or 'Exact public institution or programme name in the cited primary document; no ownership, political, family or beneficial-owner inference.', summary=summary, **dims(ids, ['organisations'], national)))

def amount(value, unit, stage, period):
    return dict(value=value, currency='INR', unit=unit, stage=stage, period=period)

def record(id, title, summary, ids, entities, relationships, response, kind='investigation-case', tier='documented', date='2020-09-23', period='2013–2019 audit period; dated responses through July 2020', amounts=None, alternatives=None, limitations=None):
    S['records'].append(dict(id=id, title=title, summary=summary, kind=kind, tier=tier, status='historical-audit-finding-with-dated-response' if kind in ['investigation-case', 'audit-finding'] else 'dated-public-record-not-allegation', statusAsOf=date, fromDate=None, toDate=None, dateBasis='Date is the latest retained specific source or response. Conduct and fiscal periods are separate; publication does not establish continuing misconduct.', entityIds=entities, relationshipIds=relationships, period=period, response=response, alternativeExplanations=alternatives or ['An audit or procurement concern establishes the stated control issue, not bribery, diversion, a criminal conviction or a quantified financial loss.'], falsifier='Revise on authenticated procurement files, reconciled ledgers, subsequent audit acceptance, contract completion records or a contrary court determination. A missing response is not an admission.', amounts=amounts or [], **dims(ids, limitations=limitations)))

def edge(id, frm, to, label, summary, ids, records, responseids=None, kind='procurement', date='2020-09-23', amounts=None, tier='documented', national=False, alternatives=None):
    S['relationships'].append(dict(id=id, **{'from': frm, 'to': to}, kind=kind, label=label, summary=summary, tier=tier, status='dated-source-record-not-proof-of-corruption', statusAsOf=date, fromDate=None, toDate=None, dateBasis='Source/status date only; historic tender and financial periods stated explicitly.', alternativeExplanations=alternatives or ['Institutional role or commercial participation alone does not establish wrongdoing. Read the linked audit scope, departmental response and financial stage.'], falsifier='Corrected original documents or proof of a different contracting legal entity would require revision; no hidden ownership or payment route is inferred.', responseIds=responseids or [], recordIds=records, amounts=amounts or [], **dims(ids, national=national)))

