edge('radio-mci','delhi-police','mobile-communication','₹185 crore quoted bid, not award', 'Latest retained parliamentary response identifies the bidder and price stage. ₹120 crore is the departmental estimate, not an amount paid.', ['pac140-2024','pac32-2025'], ['radio-case','radio-response'], ['radio-response'], date='2025-08-05', amounts=[amount(185,'crore','quoted bid including taxes; not award or payment','27 August 2024')], kind='tender-participation')
